    def allow(self, key, now):
        try:
            now = float(now)
        except Exception:
            raise TypeError("now must be a number")
        if key not in self._state:
            # new key starts full
            self._state[key] = [now, self.burst]
            tokens = self.burst
            last_ts = now
        else:
            last_ts, tokens = self._state[key]
            elapsed = now - last_ts
            if elapsed < 0:
                raise ValueError("now must not go backwards for a key")
            tokens = min(self.burst, tokens + elapsed * self.rate)
            last_ts = now
        # consume one token if available
        if tokens >= 1:
            tokens -= 1
            self._state[key] = [last_ts, tokens]
            return True
        else:
